SET FOREIGN_KEY_CHECKS=0;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS `adminler`;
CREATE TABLE `adminler` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kullanici_adi` varchar(20) NOT NULL,
  `sifre` varchar(64) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `blog_kategoriler`;
CREATE TABLE `blog_kategoriler` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_adi_tr` varchar(30) NOT NULL,
  `kategori_adi_en` varchar(30) NOT NULL,
  `kategori_aciklama_tr` varchar(150) NOT NULL,
  `kategori_aciklama_en` varchar(150) NOT NULL,
  `cat_url_tr` varchar(40) NOT NULL,
  `cat_url_en` varchar(40) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `bloglar`;
CREATE TABLE `bloglar` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `blog_baslik_tr` varchar(50) NOT NULL,
  `blog_baslik_en` varchar(50) NOT NULL,
  `blog_icerik_tr` text NOT NULL,
  `blog_icerik_en` text NOT NULL,
  `kategori_id` int(11) NOT NULL,
  `kapak_fotografi` varchar(255) NOT NULL,
  `meta_title_tr` varchar(50) NOT NULL,
  `meta_desc_tr` varchar(160) NOT NULL,
  `meta_keyword_tr` text NOT NULL,
  `meta_title_en` varchar(50) NOT NULL,
  `meta_desc_en` varchar(160) NOT NULL,
  `meta_keyword_en` text NOT NULL,
  `meta_url_tr` varchar(60) NOT NULL,
  `meta_url_en` varchar(60) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `global_vars`;
CREATE TABLE `global_vars` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `var_key` text NOT NULL,
  `var_value` text NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `page_hits`;
CREATE TABLE `page_hits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `page_url` varchar(255) NOT NULL,
  `referrer` text DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `page_url` (`page_url`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `proje_gorseller`;
CREATE TABLE `proje_gorseller` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `proje_id` int(11) NOT NULL,
  `gorsel_yolu` varchar(255) NOT NULL,
  `gorsel_tipi` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `projeler`;
CREATE TABLE `projeler` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `proje_baslik_tr` varchar(50) NOT NULL,
  `proje_baslik_en` varchar(50) NOT NULL,
  `proje_aciklama_tr` text NOT NULL,
  `proje_aciklama_en` text NOT NULL,
  `proje_teknolojiler` varchar(128) NOT NULL,
  `meta_title_tr` varchar(50) NOT NULL,
  `meta_desc_tr` varchar(160) NOT NULL,
  `meta_keyword_tr` text NOT NULL,
  `meta_url_tr` varchar(60) NOT NULL,
  `meta_title_en` varchar(50) NOT NULL,
  `meta_desc_en` varchar(160) NOT NULL,
  `meta_keyword_en` text NOT NULL,
  `meta_url_en` varchar(60) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


DROP TABLE IF EXISTS `themes`;
CREATE TABLE `themes` (
  `id` int(11) NOT NULL,
  `theme_name` varchar(10) NOT NULL,
  `main_color` varchar(20) NOT NULL,
  `sub_color` varchar(20) NOT NULL,
  `hover_color` varchar(20) NOT NULL,
  `active_color` varchar(20) NOT NULL,
  `text_color` varchar(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


